/* Builds the NON-PERMANENT STAFF REGISTRATION FORM PDF.
   --------------------------------------------------------------------------
   The official paper form is embedded as high-resolution PNG data so borders,
   branding, spacing and typography match the original company registration
   form exactly under any environment (local file://, localhost, or live server).
   Entered values are overlaid at measured field coordinates, and the Section 5
   declaration line receives the applicant's uppercase full name.
*/

(function (root) {
  'use strict';

  var FORM_IMAGE_DATA = "data:image/png;base64,";

  var PNG_W = 996;
  var PNG_H = 1578;
  var PAGE_W = 595.28;
  var PAGE_H = 841.89;
  var SCALE = PAGE_H / PNG_H;
  var IMG_W = PNG_W * SCALE;
  var X0 = (PAGE_W - IMG_W) / 2;

  var VALUE_PAD = 13; // px — padding to the right of each section's divider
  var VALUE_MAX_X = 908; // px — right padding inside the box
  var BASELINE_OFFSET = 6; // px — moves the baseline to the optical centre of a row
  var FONT_SIZE = 9.4; // pt — matches the original label scale

  /* Label/value divider (px) measured per section of the original form PNG. */
  var DIVIDERS = {
    s1: 277.5,
    s2: 283.5,
    s3: 290.5,
    s4: 328.5
  };

  /* Row centres measured from the original form PNG (px). */
  var FIELDS = [
    { key: "surname", y: 334.5, div: "s1" },
    { key: "firstName", y: 374.5, div: "s1" },
    { key: "otherNames", y: 411, div: "s1" },
    { key: "dateOfBirth", y: 448, div: "s1" },
    { key: "gender", y: 485, div: "s1" },
    { key: "nationality", y: 522.5, div: "s1" },
    { key: "homeTown", y: 560, div: "s1" },
    { key: "profession", y: 600, div: "s1" },
    { key: "phoneNumber", y: 689, div: "s2" },
    { key: "staffId", y: 731.5, div: "s2" },
    { key: "ssnitNumber", y: 771.5, div: "s2" },
    { key: "ghanaCardNo", y: 812.5, div: "s2" },
    { key: "residentialAddress", y: 917.5, div: "s3", wrap: true },
    { key: "spouseName", y: 975.5, div: "s3" },
    { key: "fathersName", y: 1014.5, div: "s3" },
    { key: "mothersName", y: 1056, div: "s3" },
    { key: "nextOfKin", y: 1145, div: "s4" },
    { key: "nextOfKinContact", y: 1185, div: "s4" },
    { key: "emergencyContactPerson", y: 1222, div: "s4" },
    { key: "emergencyContactPhone", y: 1258, div: "s4" }
  ];

  /* Declaration line (px, measured on the form PNG).
     The printed "I" stands on baseline y = 1347 (its last pixel row is 1346) and the dotted line is drawn on
     exactly the same rows, so the applicant's name is written with its baseline on that same line and
     starts where the dots start. The dotted line itself is left untouched - the name is written ON it. */
  var DECLARATION = {
    textX: 98,          // first dot is at x = 96
    textBaseline: 1347, // same baseline as the printed "I"
    maxWidthX: 908,     // right padding inside the box
    fontSize: 8.2       // cap height ~ the printed "I" (11 px)
  };

  var pxX = function (px) { return X0 + px * SCALE; };
  var pxY = function (py) { return py * SCALE; };

  function fitText(doc, text, maxWidth, startSize, minSize) {
    var size = startSize;
    doc.setFontSize(size);
    while (doc.getTextWidth(text) > maxWidth && size > minSize) {
      size -= 0.25;
      doc.setFontSize(size);
    }
    return size;
  }

  function wrapText(doc, text, maxWidth, startSize, minSize, maxLines) {
    var size = startSize;
    doc.setFontSize(size);
    var lines = doc.splitTextToSize(text, maxWidth);
    while (lines.length > maxLines && size > minSize) {
      size -= 0.25;
      doc.setFontSize(size);
      lines = doc.splitTextToSize(text, maxWidth);
    }
    if (lines.length > maxLines) {
      lines = lines.slice(0, maxLines);
      var last = lines[maxLines - 1];
      lines[maxLines - 1] = last.slice(0, Math.max(0, last.length - 1)) + '…';
    }
    return { lines: lines, size: size };
  }

  function buildRegistrationPdf(values) {
    return new Promise(function (resolve, reject) {
      try {
        var jspdfObj = (root && root.jspdf) || (typeof window !== 'undefined' && window.jspdf);
        if (!jspdfObj || !jspdfObj.jsPDF) {
          throw new Error('jsPDF is not loaded. Cannot generate the registration PDF.');
        }
        var doc = new jspdfObj.jsPDF({ orientation: 'portrait', unit: 'pt', format: 'a4' });

        doc.addImage(FORM_IMAGE_DATA, 'PNG', X0, 0, IMG_W, PAGE_H, undefined, 'FAST');
        doc.setTextColor(22, 24, 34);
        doc.setFont('helvetica', 'normal');

        FIELDS.forEach(function (field) {
          var raw = ((values && values[field.key]) || '').trim();
          if (!raw) return;

          var valueX = DIVIDERS[field.div] + VALUE_PAD;
          var maxWidth = (VALUE_MAX_X - valueX) * SCALE;
          var x = pxX(valueX);
          var baseline = pxY(field.y + BASELINE_OFFSET);

          if (field.wrap) {
            var wrapped = wrapText(doc, raw, maxWidth, FONT_SIZE, 6.5, 2);
            doc.setFontSize(wrapped.size);
            wrapped.lines.forEach(function (line, index) {
              doc.text(line, x, baseline - (wrapped.lines.length - 1 - index) * (wrapped.size * 1.18));
            });
          } else {
            fitText(doc, raw, maxWidth, FONT_SIZE, 6.5);
            doc.text(raw, x, baseline);
            doc.setFontSize(FONT_SIZE);
          }
        });

        /* Section 5 — dynamic uppercase declaration on the dotted line. */
        var fullName = [values.surname, values.firstName, values.otherNames]
          .map(function (part) { return (part || '').trim(); })
          .filter(Boolean)
          .join(' ')
          .toUpperCase();

        if (fullName) {
          var maxDecWidth = pxX(DECLARATION.maxWidthX) - pxX(DECLARATION.textX);
          fitText(doc, fullName, maxDecWidth, DECLARATION.fontSize, 5.5);
          doc.text(fullName, pxX(DECLARATION.textX), pxY(DECLARATION.textBaseline));
          doc.setFontSize(FONT_SIZE);
        }

        resolve(doc);
      } catch (err) {
        reject(err);
      }
    });
  }

  function registrationPdfFilename(values) {
    var parts = [values.surname, values.firstName, values.otherNames]
      .map(function (part) { return (part || '').trim().toUpperCase(); })
      .filter(Boolean);
    var base = parts.length ? parts.join(' ') : 'APPLICANT';
    var cleaned = base
      .replace(/[\\/:*?"<>|]/g, '')
      .replace(/\s+/g, ' ')
      .trim();
    return (cleaned || 'APPLICANT') + "'s STAFF REGISTRATION FORM.pdf";
  }

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
      buildRegistrationPdf: buildRegistrationPdf,
      registrationPdfFilename: registrationPdfFilename
    };
  }

  if (root) {
    root.buildRegistrationPdf = buildRegistrationPdf;
    root.registrationPdfFilename = registrationPdfFilename;
  }
})(typeof window !== 'undefined' ? window : this);
